const parts = msg.topic.split('/');
const sensorType = parts[2] || 'mqtt_value';
const units = {
    temperature: '°C',
    vibration: 'mm/s',
    pressure: 'PSI',
    current: 'A',
    oil_level: '%',
    humidity: '%',
    runtime_hours: 'h',
    rpm: 'RPM'
};

let value = msg.payload;
if (typeof value === 'object' && value !== null) {
    value = value.value ?? value.payload;
}
value = parseFloat(value);
if (!Number.isFinite(value)) {
    node.warn(`Invalid numeric payload on ${msg.topic}`);
    return null;
}

msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer myncel_dt_REPLACE_WITH_DEVICE_TOKEN'
};
msg.payload = {
    readings: [{
        type: sensorType,
        value,
        unit: units[sensorType] || '',
        recordedAt: new Date().toISOString()
    }]
};
msg.url = 'https://YOUR-MYNCEL-DOMAIN.com/api/iot/ingest';
return msg;
